type S4I18nText = {
  ko: string;
  uz: string;
  en: string;
  ru: string;
};

type S4I18nOptions = {
  ko: string[];
  uz: string[];
  en: string[];
  ru: string[];
};

const S4_NATIVE_DISTRACTORS: S4I18nOptions = {
  ko: ['really', 'usually', 'nearby', 'sometimes'],
  uz: ['haqiqatan', 'odatda', 'yaqin', 'ba’zan'],
  en: ['really', 'usually', 'nearby', 'sometimes'],
  ru: ['действительно', 'обычно', 'рядом', 'иногда'],
};

const normalizeS4BuilderAnswer = (value: string) =>
  value
    .replace(/[.!?,]/g, '')
    .replace(/\s+/g, ' ')
    .trim();

const normalizeS4BuilderTranslations = (
  value?: Partial<S4I18nText>,
): S4I18nText => {
  const en = normalizeS4BuilderAnswer(value?.en || value?.ko || '');

  return {
    // 한국어 UI에서 정답 한국어가 그대로 노출되지 않도록 영어 의미 사용
    ko: en,
    uz: normalizeS4BuilderAnswer(value?.uz || en),
    en,
    ru: normalizeS4BuilderAnswer(value?.ru || en),
  };
};

const shuffledS4BuilderOptions = (
  answer: string,
  distractors: string[],
): string[] => {
  const chunks = normalizeS4BuilderAnswer(answer).split(' ').filter(Boolean);

  const extras = distractors
    .filter((item) => !chunks.includes(item))
    .slice(0, chunks.length >= 6 ? 3 : 2);

  const options = [...chunks, ...extras];

  if (options.length <= 2) {
    return options.reverse();
  }

  return [...options.slice(2), ...options.slice(0, 2)];
};

const localizedS4BuilderOptions = (answer: S4I18nText): S4I18nOptions => ({
  ko: shuffledS4BuilderOptions(answer.ko, S4_NATIVE_DISTRACTORS.ko),
  uz: shuffledS4BuilderOptions(answer.uz, S4_NATIVE_DISTRACTORS.uz),
  en: shuffledS4BuilderOptions(answer.en, S4_NATIVE_DISTRACTORS.en),
  ru: shuffledS4BuilderOptions(answer.ru, S4_NATIVE_DISTRACTORS.ru),
});

const withS4SentenceBuilders = (
  questions: Record<string, Record<string, any>>,
) =>
  Object.fromEntries(
    Object.entries(questions).map(([id, question]) => {
      if (question.type !== 'sentence_builder') {
        return [id, question];
      }

      const answerI18n = normalizeS4BuilderTranslations(
        question.answerTranslation,
      );

      return [
        id,
        {
          ...question,
          instruction: I.listenNative,
          audioText: question.audioText || question.answer,
          answerI18n,
          optionsI18n: localizedS4BuilderOptions(answerI18n),
        },
      ];
    }),
  );

