  // ──────────────────────────────────────────────────────────
  // Lesson 5 · 세 집 중 어디가 가장 잘 맞아요?
  //
  // 교재 p.103 말하기 광고
  //
  // A 원룸
  // - 지하철역 5분 거리
  // - 보증금 1000만 원
  // - 월세 40만 원
  // - 방이 넓고 깨끗함
  // - 침대 / 책상 / 냉장고 / 에어컨 있음
  //
  // B 원룸 전세
  // - 서울대학교 근처
  // - 보증금 4000만 원
  // - 침대 / 에어컨 있음
  // - 인터넷 무료 사용
  //
  // C 고시원(1인실)
  // - 서울대학교 앞
  // - 월세 25만 원
  // - 침대 / 옷장 / 책상
